(async()=>{try{const [response,settings]=await Promise.all([window.KiddoAPI.fetch('/api/products'),window.KiddoAPI.fetch('/api/settings')]);if(!response.ok||!settings.ok)throw new Error();window.KIDDO_PRODUCTS=await response.json();window.KIDDO_SETTINGS=await settings.json();const script=document.createElement('script');script.src='app.js?v=20261021-zoom';script.onload=()=>{const extras=document.createElement('script');extras.src='shop-extras.js?v=20261021-zoom';document.body.append(extras);};document.body.append(script);}catch{document.querySelector('#products').innerHTML='<p class="empty">Products could not be loaded. Please refresh the page or call +880 1610-288554.</p>';}})();
